import java.util.*;
import java.text.*;
public class ComputeDate {
  public static void main(String[] a) throws Exception {
    TimeZone tz = TimeZone.getTimeZone("GMT");
    Calendar c = new GregorianCalendar(tz, Locale.US);
    c.clear();
    c.set(2014, Calendar.FEBRUARY, 3, 5, 6, 7);
    c.set(Calendar.MILLISECOND, 8);
    Date d = c.getTime();
    SimpleDateFormat sdf = new SimpleDateFormat("EEEE EEE MMMM MMM yyyy yy G a", Locale.US);
    sdf.setTimeZone(tz);
    System.out.println(sdf.format(d));
    System.out.println("millis=" + d.getTime());
    System.out.println("dayOfWeek=" + c.get(Calendar.DAY_OF_WEEK));
    System.out.println("dayOfYear=" + c.get(Calendar.DAY_OF_YEAR));
    System.out.println("weekOfYear=" + c.get(Calendar.WEEK_OF_YEAR));
    System.out.println("weekOfMonth=" + c.get(Calendar.WEEK_OF_MONTH));
    System.out.println("dayOfWeekInMonth=" + c.get(Calendar.DAY_OF_WEEK_IN_MONTH));

    // midnight test
    Calendar c2 = new GregorianCalendar(tz, Locale.US);
    c2.clear();
    c2.set(2014, Calendar.FEBRUARY, 3, 0, 0, 0);
    Date d2 = c2.getTime();
    System.out.println("midnightMillis=" + d2.getTime());
  }
}
EOF
javac -d /tmp /tmp/ComputeDate.java && java -cp /tmp ComputeDate
